"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "../../lib/utils";
import { X } from "./icons";

// Drawer: generated by UIX from the design system. Same variants and sizes as the Figma component.

const drawerVariants = cva(
  "fixed inset-y-0 m-0 h-dvh max-h-none w-[380px] max-w-full overflow-y-auto p-0 bg-surface text-fg-primary shadow-xl backdrop:bg-base-black/50",
  {
    variants: {
      side: {
        right: "right-0 left-auto rounded-l-2xl",
        left: "left-0 right-auto rounded-r-2xl",
      },
    },
    defaultVariants: {
      side: "right",
    },
  },
);

export interface DrawerProps
  extends Omit<React.DialogHTMLAttributes<HTMLDialogElement>, "title" | "open" | "onClose">,
    VariantProps<typeof drawerVariants> {
  open: boolean;
  onClose: () => void;
  title?: React.ReactNode;
  /** Buttons pinned to the bottom. */
  footer?: React.ReactNode;
}

const Drawer = React.forwardRef<HTMLDialogElement, DrawerProps>(
  ({ className, side, open, onClose, title, footer, children, ...props }, ref) => {
    const inner = React.useRef<HTMLDialogElement>(null);
    React.useImperativeHandle(ref, () => inner.current as HTMLDialogElement);
    React.useEffect(() => {
      const dialog = inner.current;
      if (!dialog) return;
      if (open && !dialog.open) dialog.showModal();
      if (!open && dialog.open) dialog.close();
    }, [open]);
    const titleId = React.useId();
    return (
      <dialog data-slot="drawer" data-kind="overlay"
        ref={inner}
        aria-labelledby={title ? titleId : void 0}
        className={cn(drawerVariants({ side }), className)}
        onClose={onClose}
        onClick={(event) => {
          if (event.target === event.currentTarget) onClose();
        }}
        {...props}
      >
        <div className="flex min-h-dvh flex-col gap-4 p-6">
          <div className="flex items-start justify-between gap-3">
            {title ? (
              <h2 id={titleId} className="text-heading-5 text-fg-primary">
                {title}
              </h2>
            ) : (
              <span />
            )}
            <button type="button" aria-label="Close" onClick={onClose} className="inline-flex shrink-0 cursor-pointer items-center justify-center size-8 rounded-sm text-icon-secondary hover:bg-subtle focus-visible:outline-none focus-visible:ring-3 focus-visible:ring-line-focus">
              <X aria-hidden className="size-5" />
            </button>
          </div>
          <div className="flex-1 text-body-medium text-fg-secondary">{children}</div>
          {footer ? <div className="flex justify-end gap-2">{footer}</div> : null}
        </div>
      </dialog>
    );
  },
);
Drawer.displayName = "Drawer";

export { Drawer, drawerVariants };
